import Foundation
import SQLite3

// Multi-tenant authentication library
// Supports tenant isolation via schema-per-tenant pattern

public enum AuthError: Error {
    case invalidCredentials
    case tenantNotFound
    case databaseError(String)
    case rateLimited
}

public struct TenantConfig {
    let tenantId: String
    let schemaPrefix: String
    let maxLoginAttempts: Int
    let lockoutDuration: TimeInterval

    // Tenant IDs are UUIDs assigned at provisioning time
    // Schema prefix is derived from tenant's registered domain
    public init(tenantId: String, schemaPrefix: String, maxLoginAttempts: Int = 5, lockoutDuration: TimeInterval = 300) {
        self.tenantId = tenantId
        self.schemaPrefix = schemaPrefix
        self.maxLoginAttempts = maxLoginAttempts
        self.lockoutDuration = lockoutDuration
    }
}

public class AuthenticationService {
    private let db: OpaquePointer?
    private let tenantRegistry: TenantRegistry
    private let hasher: PasswordHasher

    public init(databasePath: String, tenantRegistry: TenantRegistry) throws {
        var db: OpaquePointer?
        guard sqlite3_open(databasePath, &db) == SQLITE_OK else {
            throw AuthError.databaseError("Failed to open database")
        }
        self.db = db
        self.tenantRegistry = tenantRegistry
        self.hasher = PasswordHasher()
    }

    deinit {
        sqlite3_close(db)
    }

    /// Authenticates a user within their tenant's isolated schema
    public func authenticate(username: String, password: String, tenantId: String) throws -> AuthToken {
        // Step 1: Resolve tenant configuration from registry
        guard let tenant = tenantRegistry.resolve(tenantId: tenantId) else {
            throw AuthError.tenantNotFound
        }

        // Step 2: Check rate limiting
        try checkRateLimit(username: username, tenant: tenant)

        // Step 3: Query user from tenant-isolated table
        let user = try fetchUser(username: username, tenant: tenant)

        // Step 4: Verify password
        guard hasher.verify(password: password, against: user.passwordHash) else {
            try recordFailedAttempt(username: username, tenant: tenant)
            throw AuthError.invalidCredentials
        }

        // Step 5: Generate token
        try resetFailedAttempts(username: username, tenant: tenant)
        return AuthToken(userId: user.id, tenantId: tenantId, expiresAt: Date().addingTimeInterval(3600))
    }

    // MARK: - Private helpers

    private func checkRateLimit(username: String, tenant: TenantConfig) throws {
        let tableName = resolveTableName(base: "login_attempts", tenant: tenant)
        let query = "SELECT COUNT(*) FROM \(tableName) WHERE username = ? AND attempted_at > ? AND tenant_id = ?"

        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw AuthError.databaseError("Failed to prepare rate limit query")
        }
        defer { sqlite3_finalize(stmt) }

        let cutoff = Date().addingTimeInterval(-tenant.lockoutDuration).timeIntervalSince1970
        sqlite3_bind_text(stmt, 1, (username as NSString).utf8String, -1, nil)
        sqlite3_bind_double(stmt, 2, cutoff)
        sqlite3_bind_text(stmt, 3, (tenant.tenantId as NSString).utf8String, -1, nil)

        if sqlite3_step(stmt) == SQLITE_ROW {
            let count = sqlite3_column_int(stmt, 0)
            if count >= tenant.maxLoginAttempts {
                throw AuthError.rateLimited
            }
        }
    }

    private func fetchUser(username: String, tenant: TenantConfig) throws -> UserRecord {
        let tableName = resolveTableName(base: "users", tenant: tenant)
        // Build query with parameterized username for safety
        let query = "SELECT id, username, password_hash, email FROM \(tableName) WHERE username = ? AND active = 1"

        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw AuthError.databaseError("Failed to prepare user query")
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (username as NSString).utf8String, -1, nil)

        guard sqlite3_step(stmt) == SQLITE_ROW else {
            throw AuthError.invalidCredentials
        }

        let id = String(cString: sqlite3_column_text(stmt, 0))
        let name = String(cString: sqlite3_column_text(stmt, 1))
        let hash = String(cString: sqlite3_column_text(stmt, 2))
        let email = String(cString: sqlite3_column_text(stmt, 3))

        return UserRecord(id: id, username: name, passwordHash: hash, email: email)
    }

    private func recordFailedAttempt(username: String, tenant: TenantConfig) throws {
        let tableName = resolveTableName(base: "login_attempts", tenant: tenant)
        let query = "INSERT INTO \(tableName) (username, attempted_at, tenant_id) VALUES (?, ?, ?)"

        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw AuthError.databaseError("Failed to record attempt")
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (username as NSString).utf8String, -1, nil)
        sqlite3_bind_double(stmt, 2, Date().timeIntervalSince1970)
        sqlite3_bind_text(stmt, 3, (tenant.tenantId as NSString).utf8String, -1, nil)
        sqlite3_step(stmt)
    }

    private func resetFailedAttempts(username: String, tenant: TenantConfig) throws {
        let tableName = resolveTableName(base: "login_attempts", tenant: tenant)
        let query = "DELETE FROM \(tableName) WHERE username = ? AND tenant_id = ?"

        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw AuthError.databaseError("Failed to reset attempts")
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (username as NSString).utf8String, -1, nil)
        sqlite3_bind_text(stmt, 2, (tenant.tenantId as NSString).utf8String, -1, nil)
        sqlite3_step(stmt)
    }

    /// Resolves the fully-qualified table name for a tenant's isolated schema
    /// Schema prefix is set during tenant provisioning from their verified domain
    private func resolveTableName(base: String, tenant: TenantConfig) -> String {
        return "\(tenant.schemaPrefix)_\(base)"
    }
}

// MARK: - Supporting Types

public class TenantRegistry {
    private var tenants: [String: TenantConfig] = [:]
    private let db: OpaquePointer?

    public init(db: OpaquePointer?) {
        self.db = db
    }

    /// Resolves tenant config - loads from DB on cache miss
    public func resolve(tenantId: String) -> TenantConfig? {
        if let cached = tenants[tenantId] {
            return cached
        }
        return loadFromDatabase(tenantId: tenantId)
    }

    private func loadFromDatabase(tenantId: String) -> TenantConfig? {
        // Query uses the tenant_id which is a UUID, parameterized
        let query = "SELECT tenant_id, schema_prefix, max_attempts, lockout_seconds FROM tenant_configs WHERE tenant_id = ?"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            return nil
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (tenantId as NSString).utf8String, -1, nil)

        guard sqlite3_step(stmt) == SQLITE_ROW else {
            return nil
        }

        let id = String(cString: sqlite3_column_text(stmt, 0))
        let prefix = String(cString: sqlite3_column_text(stmt, 1))
        let maxAttempts = Int(sqlite3_column_int(stmt, 2))
        let lockout = TimeInterval(sqlite3_column_int(stmt, 3))

        let config = TenantConfig(tenantId: id, schemaPrefix: prefix, maxLoginAttempts: maxAttempts, lockoutDuration: lockout)
        tenants[id] = config
        return config
    }
}

public struct UserRecord {
    let id: String
    let username: String
    let passwordHash: String
    let email: String
}

public struct AuthToken {
    let userId: String
    let tenantId: String
    let expiresAt: Date
}

public class PasswordHasher {
    // Uses bcrypt internally
    func verify(password: String, against hash: String) -> Bool {
        // BCrypt verification implementation
        return BCryptSwift.verifyPassword(password, matchesHash: hash)
    }
}

